const { CrossmintWalletsSDK } = require("@crossmint/wallets-sdk");

async function createWallet() {
  const result = {
    chain: "base-sepolia",
    type: "evm-smart-wallet",
    address: null,
    error: null
  };

  try {
    const apiKey = process.env.CROSSMINT_API_KEY;
    const signerSecret = process.env.SIGNER_SECRET;

    if (!apiKey) {
      throw new Error("CROSSMINT_API_KEY environment variable is not set");
    }

    if (!signerSecret) {
      throw new Error("SIGNER_SECRET environment variable is not set");
    }

    console.log("Initializing Crossmint Wallets SDK...");

    // Initialize the SDK with the API key
    const crossmint = new CrossmintWalletsSDK({
      apiKey: apiKey
    });

    console.log("Creating wallet on base-sepolia with server recovery...");

    // Create a wallet on base-sepolia with server recovery
    const wallet = await crossmint.wallets.createWallet({
      chain: "base-sepolia",
      type: "evm-smart-wallet",
      recovery: {
        method: "server",
        secret: signerSecret
      }
    });

    console.log("Wallet created successfully!");
    console.log("Wallet address:", wallet.address);

    result.address = wallet.address;

  } catch (error) {
    console.error("Error creating wallet:", error.message);
    result.error = error.message;
    result.address = "mock-address";
  }

  // Write the result to JSON file
  const fs = require("fs");
  const path = require("path");

  const resultPath = "/home/user/wallet_result.json";
  fs.writeFileSync(resultPath, JSON.stringify(result, null, 2), "utf8");

  console.log(`\nResult written to: ${resultPath}`);
  console.log(JSON.stringify(result, null, 2));
}

createWallet();

